// backend/src/core/ai/llm/llm.adapter.ts
import type { StrategyResponse, ProposedAction } from '../strategy/strategy.types';
import type { ChatMessage } from '../memory/memory.types';

interface LLMAdapter {
  generateStrategy(message: string, mode: string, history: ChatMessage[]): Promise<StrategyResponse>;
}

class OpenAIAdapter implements LLMAdapter {
  private apiKey: string;
  private apiUrl = 'https://api.openai.com/v1/chat/completions';
  private timeoutMs: number;
  private maxContextChars: number;

  constructor(apiKey: string) {
    this.apiKey = apiKey;
    this.timeoutMs = parseInt(process.env.AI_LLM_TIMEOUT_MS || '8000', 10);
    this.maxContextChars = parseInt(process.env.AI_MAX_CONTEXT_CHARS || '2000', 10);
  }

  private truncateContext(context: string, maxChars: number): string {
    if (context.length <= maxChars) {
      return context;
    }
    return context.substring(0, maxChars - 3) + '...';
  }

  async generateStrategy(message: string, mode: string, history: ChatMessage[]): Promise<StrategyResponse> {
    const startTime = Date.now();

    try {
      console.info(`[LLM] Iniciando geração de estratégia - modo: ${mode}, histórico: ${history.length} mensagens`);

      // Construir contexto do histórico (últimas 5 mensagens)
      let historyContext = history
        .slice(-5)
        .map((msg) => `${msg.role}: ${msg.content}`)
        .join('\n');

      // Truncar contexto se exceder limite
      historyContext = this.truncateContext(historyContext, this.maxContextChars);

      const systemPrompt = `Você é um assistente de estratégia do Unificard. Analise a solicitação do usuário e proponha uma estratégia.

Modo atual: ${mode}
Contexto do histórico:
${historyContext || 'Nenhum histórico disponível'}

Responda APENAS com um JSON válido no formato:
{
  "summary": "resumo da estratégia",
  "proposed_actions": [
    {
      "id": "1",
      "type": "tipo_da_acao",
      "description": "descrição",
      "requires_approval": true/false
    }
  ],
  "risk_level": "low" | "medium" | "high"
}

IMPORTANTE: NÃO execute ações. Apenas proponha estratégias.`;

      const userPrompt = `Solicitação do usuário: ${message}`;

      const controller = new AbortController();
      const timeoutId = setTimeout(() => {
        controller.abort();
        console.error(`[LLM] Timeout após ${this.timeoutMs}ms`);
      }, this.timeoutMs);

      try {
        const response = await fetch(this.apiUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${this.apiKey}`,
          },
          body: JSON.stringify({
            model: 'gpt-3.5-turbo',
            messages: [
              { role: 'system', content: systemPrompt },
              { role: 'user', content: userPrompt },
            ],
            temperature: 0.7,
            max_tokens: 500,
          }),
          signal: controller.signal,
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
          const errorText = await response.text().catch(() => '');
          throw new Error(`OpenAI API error: ${response.status} - ${errorText}`);
        }

        const data = await response.json() as { choices?: Array<{ message?: { content?: string } }> };
        const content = data.choices?.[0]?.message?.content;

        if (!content) {
          throw new Error('Resposta vazia da API');
        }

        // Extrair JSON da resposta
        const jsonMatch = content.match(/\{[\s\S]*\}/);
        if (!jsonMatch) {
          throw new Error('JSON não encontrado na resposta');
        }

        const strategy: StrategyResponse = JSON.parse(jsonMatch[0]);

        // Validar estrutura
        if (!strategy.summary || !Array.isArray(strategy.proposed_actions) || !strategy.risk_level) {
          throw new Error('Estrutura de resposta inválida');
        }

        const duration = Date.now() - startTime;
        console.info(`[LLM] Estratégia gerada com sucesso em ${duration}ms`);

        return strategy;
      } catch (fetchError: any) {
        clearTimeout(timeoutId);
        
        if (fetchError.name === 'AbortError') {
          throw new Error(`Timeout: requisição cancelada após ${this.timeoutMs}ms`);
        }
        throw fetchError;
      }
    } catch (error: any) {
      const duration = Date.now() - startTime;
      console.error(`[LLM] Erro ao chamar OpenAI após ${duration}ms:`, error.message || error);
      throw error;
    }
  }
}

class MockAdapter implements LLMAdapter {
  async generateStrategy(message: string, mode: string, history: ChatMessage[]): Promise<StrategyResponse> {
    // Resposta mock baseada no modo
    let summary = '';
    let riskLevel: 'low' | 'medium' | 'high' = 'low';
    const proposedActions: ProposedAction[] = [];

    if (mode === 'engenharia') {
      summary = `Estratégia proposta para: ${message}. Baseado no histórico (${history.length} mensagens), sugiro análise de código e revisão de arquitetura.`;
      riskLevel = 'high';
      proposedActions.push(
        {
          id: '1',
          type: 'read_files',
          description: 'Ler arquivos relacionados ao projeto',
          requires_approval: true,
        },
        {
          id: '2',
          type: 'analyze_code',
          description: 'Analisar estrutura do código',
          requires_approval: false,
        }
      );
    } else if (mode === 'profissional') {
      summary = `Estratégia profissional para: ${message}. Considerando o contexto do histórico.`;
      riskLevel = 'medium';
      proposedActions.push({
        id: '1',
        type: 'suggest_improvement',
        description: 'Sugerir melhorias no perfil profissional',
        requires_approval: false,
      });
    } else {
      summary = `Estratégia proposta para: ${message}. Modo: ${mode}.`;
      riskLevel = 'low';
      proposedActions.push({
        id: '1',
        type: 'general_advice',
        description: 'Fornecer orientação geral',
        requires_approval: false,
      });
    }

    return {
      summary,
      proposed_actions: proposedActions,
      risk_level: riskLevel,
    };
  }
}

// Factory function
export function createLLMAdapter(): LLMAdapter {
  const apiKey = process.env.OPENAI_API_KEY;

  if (apiKey && apiKey.trim() !== '') {
    console.info('[LLM] Adapter OpenAI configurado');
    return new OpenAIAdapter(apiKey);
  }

  console.info('[LLM] Modo MOCK ativado (OPENAI_API_KEY não configurada)');
  return new MockAdapter();
}

